class Notifications::SettingsController < ApplicationController
  def show
    @boards = Current.user.boards.alphabetically
    @settings = Current.user.settings
  end

  def update
    set_settings
    @settings.bundle_email_frequency = bundle_email_frequency_param if bundle_email_frequency_param.present?
    @settings.save!

    respond_to do |format|
      format.html { redirect_to notifications_settings_path }
      format.json { head :no_content }
      format.turbo_stream { head :no_content }
    end
  rescue ArgumentError, ActiveRecord::RecordInvalid
    respond_to do |format|
      format.html { redirect_to notifications_settings_path, alert: "That email frequency is not valid" }
      format.json { head :unprocessable_entity }
      format.turbo_stream { head :unprocessable_entity }
    end
  end

  private
    def set_settings
      @settings = Current.user.settings
    end

    def bundle_email_frequency_param
      params.dig(:settings, :bundle_email_frequency) ||
        params.dig(:user_settings, :bundle_email_frequency) ||
        params.dig(:user, :bundle_email_frequency) ||
        params[:bundle_email_frequency]
    end
end
